// Skill Galaxy — Planet Earth and Time Tunnel questions.
// Questions written for Skill Galaxy; topics from the Marble Skill Taxonomy (CC BY-SA 4.0).
SG_Q({
  // ===================== PLANET EARTH =====================

  // Tectonic Plates
  "mt_XrvPx5kUfO": [
    { q: "What are tectonic plates?", a: ["Huge slabs of Earth's crust that slowly move", "Layers of ice covering the North and South Poles", "Flat rocks laid down at the bottom of the sea", "Clouds of gas high up in the atmosphere"], why: "Earth's outer layer is cracked into giant pieces called tectonic plates. They fit together like a jigsaw and move very slowly." },
    { q: "About how fast do tectonic plates move?", a: ["A few centimetres per year", "A few metres per day", "A few kilometres per year", "They never move at all"], why: "Plates move at roughly the speed your fingernails grow: a few centimetres a year. Over millions of years that adds up to thousands of kilometres." },
    { q: "What do tectonic plates rest on?", a: ["Hot, soft rock in the mantle", "A layer of cold seawater", "The solid iron inner core", "A layer of air under the crust"], why: "Below the crust is the mantle. Its upper part is so hot that the rock is soft and can flow very slowly, so the plates on top can move." },
    { q: "Which is the best description of Earth's crust?", a: ["Broken into large pieces that fit together", "One single unbroken shell of solid rock", "Made of melted rock that flows like water", "The hottest layer, right at Earth's centre"], why: "The crust is not one piece. It is cracked into large and small plates that fit together like a jigsaw puzzle and move against each other." },
    { q: "A plate moves 5 cm each year. About how far will it move in 100 years?", a: ["5 metres", "50 centimetres", "5 kilometres", "500 metres"], why: "5 cm × 100 = 500 cm, which is 5 metres. Slow, but over millions of years plates can travel thousands of kilometres." },
    { q: "Why can't we feel tectonic plates moving on a normal day?", a: ["They move far too slowly to notice", "They move at night while we sleep", "They stopped moving millions of years ago", "Buildings block the movement from us"], why: "Plates creep just a few centimetres a year, far too slowly to feel. We only notice when stress builds up and is suddenly released as an earthquake." },
    { q: "Scientists measure that North America and Europe are moving about 2 to 3 cm further apart every year. What causes this?", a: ["The plates they sit on are spreading apart", "Rising sea levels are pushing them apart", "Strong ocean currents are pulling them", "The Moon's gravity drags them apart"], why: "Europe and North America sit on different plates. At the Mid-Atlantic Ridge these plates are spreading apart, so the Atlantic Ocean slowly gets wider." },
    { q: "Fossils of the same kind of land reptile are found in both South America and Africa. What does this suggest?", a: ["The two continents were once joined", "The reptile swam across the ocean", "Someone carried the fossils over", "A storm carried the reptiles across"], why: "A land reptile couldn't cross a wide ocean. Millions of years ago South America and Africa were joined, then moving plates carried them apart." }
  ],

  // Plate Boundaries
  "mt_-JnOhdei6F": [
    { q: "Where do most earthquakes and volcanoes happen?", a: ["Near the edges of tectonic plates", "In the middle of large plates", "In places with hot weather", "Near the North and South Poles"], why: "Plate edges (boundaries) are where plates push, pull and grind against each other, so that's where most earthquakes and volcanoes are found." },
    { q: "What happens at a divergent plate boundary?", a: ["Two plates move apart", "Two plates push together", "Two plates slide past each other", "One plate sinks into the core"], why: "Divergent means moving apart. Magma rises into the gap and cools to make new crust, as at the Mid-Atlantic Ridge." },
    { q: "The Himalayas formed where the Indian plate crashed into the Eurasian plate. What type of boundary is this?", a: ["Convergent (pushing together)", "Divergent (pulling apart)", "Transform (sliding past)", "There is no boundary there"], why: "When two continents collide, neither sinks easily, so the rock crumples upwards into high mountains like the Himalayas, home of Mount Everest." },
    { q: "California's San Andreas Fault is where two plates slide sideways past each other. What is this kind of boundary called?", a: ["Transform boundary", "Divergent boundary", "Convergent boundary", "Volcanic hotspot"], why: "At a transform boundary plates slide past each other sideways. The San Andreas Fault is a famous example and has many earthquakes." },
    { q: "Why do earthquakes happen where two plates slide past each other?", a: ["The plates stick, then suddenly slip", "Magma bursts up through the gap", "Ocean water seeps into the cracks", "The plates melt and sink away"], why: "The plates get locked together by friction. Stress builds up for years, then the rocks suddenly break and slip, sending out shaking waves." },
    { q: "Iceland sits on the Mid-Atlantic Ridge, where two plates are pulling apart. Why does it have so many volcanoes?", a: ["Magma rises up to fill the gap", "The plates crash and fold upwards", "The ice melts and turns into lava", "Mountains collapse into the sea"], why: "As the plates pull apart, the gap lets hot magma rise from below. It erupts as lava, which is how Iceland keeps building new land." },
    { q: "Where an ocean plate meets a continent, the ocean plate sinks beneath it. Why are volcanoes found along these boundaries?", a: ["Rock melts deep down and magma rises", "The seawater boils and then erupts", "The plates pull apart and leave a gap", "The plates slide sideways past each other"], why: "As the ocean plate sinks into the hot mantle, rock deep below melts. The magma rises through the crust above and erupts, as in the Andes in South America." },
    { q: "Why does Britain have very few strong earthquakes and no active volcanoes?", a: ["It is far from the edge of its plate", "It is surrounded by cold seawater", "Its rocks are too hard to ever break", "It sits right on a plate boundary"], why: "Britain lies in the middle of the Eurasian Plate, far from the boundaries where plates collide or pull apart. Small earthquakes happen, but big ones are rare." }
  ],

  // Eruption Types & Volcano Shape
  "mt_W4j7T_PnGH": [
    { q: "What happens in an effusive eruption?", a: ["Runny lava flows out fairly gently", "A violent blast of ash and rock", "Steam escapes but no lava comes out", "The volcano collapses into a hole"], why: "Effusive eruptions pour out runny lava that flows away steadily, as often happens in Hawaii. They rarely explode." },
    { q: "Which kind of magma is most likely to cause an explosive eruption?", a: ["Thick, sticky magma full of gas", "Thin, runny magma with little gas", "Magma with no gas in it", "Magma that has already turned solid"], why: "Gas can't escape easily from thick, sticky magma. Pressure builds up until the magma blasts out violently as ash and rock." },
    { q: "What shape is a shield volcano?", a: ["Wide with gentle slopes", "Tall with very steep sides", "A deep hole with no hill", "A thin, pointed spike"], why: "Shield volcanoes are built from runny lava that spreads far before cooling, making a broad, gently sloping mountain, like a warrior's shield lying down." },
    { q: "Why do volcanoes built from thick, sticky lava usually have steep sides?", a: ["The lava cools before it can flow far", "The wind blows the lava into a point", "The lava is runny and spreads widely", "The ground pushes the lava upwards"], why: "Sticky lava moves slowly and hardens close to the vent. Layers of lava and ash pile up near the top, building a steep cone." },
    { q: "Mauna Loa in Hawaii is a huge, gently sloping volcano built from runny lava flows. What type of volcano is it?", a: ["Shield volcano", "Composite volcano", "Extinct volcano", "Cinder cone"], why: "Mauna Loa is a classic shield volcano: its runny lava spreads out in wide sheets. It is one of the largest volcanoes on Earth." },
    { q: "A volcano has steep sides made of layers of ash and lava, and it erupts with big explosions. What kind of magma does it most likely have?", a: ["Thick and sticky with trapped gas", "Very runny with very little gas", "Cold and already solid", "Thin and watery like a stream"], why: "Steep sides and explosive blasts go together with thick, gassy magma. Mount St Helens in the USA and Vesuvius in Italy are volcanoes like this." },
    { q: "Which of these comes mainly from an explosive eruption?", a: ["A huge cloud of ash", "A slow river of runny lava", "A gentle lake of lava", "Smooth, rope-like lava rock"], why: "Explosive eruptions blast magma into tiny pieces that form ash clouds. In 2010, ash from an Icelandic volcano stopped flights across much of Europe, including the UK." },
    { q: "Scientists sometimes compare magma to a bottle of fizzy drink. What is the comparison about?", a: ["Trapped gas can burst out suddenly", "Magma is cold and full of sugar", "Both are made mostly of water", "Both are thin and flow out very fast"], why: "Gas dissolved in magma is like the fizz in a bottle. In thick magma the gas can't escape gently, so pressure builds until it bursts out explosively." }
  ],

  // Measuring Earthquake Strength
  "mt_mdZ3nBWChW": [
    { q: "Which instrument detects and records the shaking of the ground during an earthquake?", a: ["Seismometer", "Barometer", "Thermometer", "Anemometer"], why: "A seismometer senses ground movement and records it, often as a wiggly line called a seismogram. A barometer measures air pressure instead." },
    { q: "How does an earthquake's energy travel through the ground?", a: ["As waves spreading outwards", "As a flow of hot lava", "As a gust of strong wind", "As electricity in the rocks"], why: "When rocks suddenly break, energy spreads out in all directions as seismic waves, a bit like ripples spreading when you drop a stone into a pond." },
    { q: "What does the magnitude of an earthquake tell you?", a: ["How strong the earthquake was", "How long ago it happened", "How deep the sea is nearby", "Which country it started in"], why: "Magnitude is a number that describes how strong an earthquake was (how much energy it released). Bigger numbers mean much stronger earthquakes." },
    { q: "Four earthquakes were recorded. Which one was the strongest?", a: ["Magnitude 7.5", "Magnitude 5.2", "Magnitude 6.8", "Magnitude 3.9"], why: "On a magnitude scale a higher number means a stronger earthquake, so the magnitude 7.5 earthquake was the strongest." },
    { q: "What is the point underground where the rocks first break in an earthquake called?", a: ["The focus", "The epicentre", "The crater", "The summit"], why: "The focus is where the rocks break underground. The epicentre is the point on the surface directly above it, where shaking is often strongest." },
    { q: "Seismometers far from an earthquake usually record smaller wiggles than ones close to it. Why?", a: ["The waves weaken as they spread out", "The earthquake grows over time", "Faraway seismometers are broken", "The waves speed up as they travel"], why: "Seismic waves spread out from where the rocks broke and lose energy as they travel, so shaking is usually strongest near the earthquake and weaker far away." },
    { q: "Each whole step up the magnitude scale (for example from 5 to 6) means an earthquake releases about how much more energy?", a: ["About 32 times more", "About 2 times more", "About 10 times more", "About half as much"], why: "Each whole step releases about 32 times more energy, so 5 to 7 is about 1,000 times more. (It's the size of the wiggles on a seismometer that grows about 10 times.)" },
    { q: "True or false: earthquakes happen in the UK, but most are too small to feel.", a: ["True", "False"], why: "The British Geological Survey detects a few hundred earthquakes in and around the UK each year using seismometers, but most are too small for people to notice." }
  ],

  // Types of rocks
  "mt_bqL8DD1SbV": [
    { q: "How does igneous rock form?", a: ["Melted rock cools and hardens", "Layers of sediment get squashed", "Heat and pressure change old rock", "Shells dissolve in seawater"], why: "Igneous rock forms when magma or lava cools and becomes solid. Granite and basalt are igneous rocks." },
    { q: "Which type of rock forms when layers of sediment are pressed and cemented together?", a: ["Sedimentary", "Igneous", "Metamorphic", "Volcanic"], why: "Sedimentary rocks such as sandstone, chalk and limestone form from layers of sediment that build up, get squashed and stick together over a long time." },
    { q: "Marble forms when limestone is changed by great heat and pressure. What type of rock is marble?", a: ["Metamorphic", "Sedimentary", "Igneous", "Fossil"], why: "Metamorphic means 'changed form'. Heat and pressure deep underground change existing rock without melting it, turning limestone into marble and mudstone into slate." },
    { q: "Why are fossils often found in sedimentary rock but hardly ever in igneous rock?", a: ["Igneous rock forms from melted rock", "Animals avoided living near volcanoes", "Igneous rock is too dark to see them", "Sedimentary rock is much harder"], why: "Fossils form when remains are buried in layers of sediment that slowly become rock. Igneous rock forms from scorching melted rock, which would destroy remains." },
    { q: "Rock is broken down, then carried away, then dropped somewhere else. Which words name these stages in order?", a: ["Weathering, erosion, deposition", "Deposition, weathering, erosion", "Erosion, deposition, weathering", "Deposition, erosion, weathering"], why: "Weathering breaks rock down, erosion carries the pieces away, and deposition is when they are dropped, often building up new layers of sediment." },
    { q: "A rock lets water soak through it. Which word describes this rock?", a: ["Permeable", "Impermeable", "Metamorphic", "Igneous"], why: "Permeable rocks, like chalk and sandstone, have tiny gaps or cracks that let water pass through. Impermeable rocks, like granite and slate, do not." },
    { q: "The White Cliffs of Dover are made of chalk, formed from the tiny shells of sea plankton. What type of rock is chalk?", a: ["Sedimentary", "Igneous", "Metamorphic", "Magma"], why: "Chalk formed from billions of tiny plankton shells that settled on an ancient sea floor and were squashed into layers, so it is a sedimentary rock." },
    { q: "A cliff shows layers of rock called strata. If the rocks have not been disturbed, which layer is usually the oldest?", a: ["The layer at the bottom", "The layer right at the top", "The thickest layer", "The middle layer"], why: "Sediment is laid down on top of older layers, so in undisturbed strata the lowest layer formed first and is the oldest." }
  ],

  // Erosion and weathering
  "mt_vAP_A986IQ": [
    { q: "What is the difference between weathering and erosion?", a: ["Weathering breaks rock; erosion moves it", "Weathering moves rock; erosion breaks it", "They are two words for the same thing", "Erosion builds new rock from sediment"], why: "Weathering breaks rock down where it is. Erosion carries the broken bits away. Deposition is when they are finally dropped somewhere else." },
    { q: "Sand blown by strong winds slowly wears desert rocks into strange shapes. Which agent of erosion is at work?", a: ["Wind", "Ice", "Plant roots", "Rain"], why: "Wind picks up sand and blasts it against rocks, wearing them away like sandpaper. This is common in deserts, where few plants hold the sand in place." },
    { q: "Water gets into a crack in a rock, freezes, then melts, again and again. What is this process called?", a: ["Freeze-thaw weathering", "Deposition by rivers", "Erosion by wind", "Volcanic activity"], why: "Water expands by about 9% when it freezes, pushing the crack wider. After many freezes and thaws the rock splits apart." },
    { q: "Tree roots growing into cracks in an old wall slowly push the stones apart. What is this an example of?", a: ["Weathering by plants", "Deposition by wind", "Erosion by the sea", "Rock forming from lava"], why: "As roots grow they widen cracks and break rock or stone apart. Living things, including plants and burrowing animals, can cause weathering." },
    { q: "The writing on very old gravestones in a churchyard is often hard to read. What is the best explanation?", a: ["Rain has slowly weathered the stone", "The stones were carved badly at first", "The writing has sunk into the stone", "Wind has piled sand on top of them"], why: "Rainwater is slightly acidic and slowly dissolves stone such as limestone and marble. Over hundreds of years the carved letters get worn away." },
    { q: "Pupils measure how far a cliff edge moves back. It moved 2 m in 2023, 1 m in 2024 and 3 m in 2025. What was the mean rate of erosion?", a: ["2 m per year", "6 m per year", "3 m per year", "1 m per year"], why: "Add the distances (2 + 1 + 3 = 6 m) and divide by the 3 years: 6 ÷ 3 = 2 m per year. Measuring over several years gives better evidence." },
    { q: "The Holderness coast in Yorkshire has cliffs of soft clay and is one of the fastest-eroding coastlines in Europe. Why does it erode so quickly?", a: ["Soft rock is easily worn away by waves", "Hard rock there attracts bigger waves", "There is no sea along that coastline", "The cliffs are protected by sea ice"], why: "Holderness cliffs are made of soft boulder clay. Waves wear it away easily, so on average the coastline moves back by well over a metre each year." },
    { q: "Valleys in the Lake District carved by glaciers are U-shaped. What does this show?", a: ["Ice can erode rock on a huge scale", "The valleys were dug out by people", "Ice protects rock from erosion", "Rivers carved them very quickly"], why: "Glaciers are slow rivers of ice that scrape and pluck rock as they move. In the last Ice Age they carved wide U-shaped valleys in places like the Lake District." }
  ],

  // Sun-Driven Weather Systems
  "mt_-YYnLLIZh5": [
    { q: "What is the main source of the energy that drives Earth's weather?", a: ["The Sun", "The Moon", "Earth's hot core", "Volcanoes"], why: "The Sun heats Earth's land, sea and air. Differences in this heating cause winds, clouds, rain and storms." },
    { q: "On a sunny morning at the beach, which usually warms up faster?", a: ["The sand on the beach", "The water in the sea", "Both warm at the same rate", "Neither of them warms up"], why: "Land heats up and cools down much faster than water. That's why sand can feel hot while the sea still feels cool." },
    { q: "On a hot afternoon at the seaside, a cool breeze often blows from the sea onto the land. Why?", a: ["Warm air rises over land; sea air moves in", "The sea is warmer, so air rises over it", "The Moon's pull drags the air onto land", "Waves push the air up and over the beach"], why: "Land heats faster than sea. Warm air over the land rises, leaving lower pressure, and cooler air from over the sea flows in to replace it: a sea breeze." },
    { q: "Why is it hotter at the Equator than at the poles?", a: ["Sunlight hits it more directly", "It is much closer to the Sun", "The Equator has more volcanoes", "Hot air flows there from the poles"], why: "At the Equator the Sun's rays hit almost straight on, concentrating heat on a small area. Near the poles the same sunlight is spread over a larger area." },
    { q: "Which of these best describes what causes wind?", a: ["Air moving from high to low pressure", "Trees waving their branches about", "Clouds bumping into each other", "Air moving from low to high pressure"], why: "Uneven heating makes some air warm and rise (low pressure) and some cool and sink (high pressure). Air flows from high to low pressure, and we feel it as wind." },
    { q: "Warm air is less dense than cooler air around it. What does the warm air do?", a: ["It rises", "It sinks", "It stays still", "It turns to ice"], why: "Warm air expands and becomes lighter for its size, so it rises. Rising warm air leaves an area of lower pressure near the ground." },
    { q: "In the UK, an area of high pressure in summer usually brings what kind of weather?", a: ["Dry, settled and often sunny", "Heavy rain and strong winds", "Thunderstorms every afternoon", "Snow and freezing fog"], why: "In high pressure, air sinks, which stops clouds forming, giving calm, dry weather. Low pressure (rising air) brings clouds, wind and rain." },
    { q: "Ocean currents carry warm water from near the Equator towards the poles. What does this do?", a: ["Moves heat around the planet", "Stops the Sun heating the sea", "Makes the poles hotter than the Equator", "Causes earthquakes along the coast"], why: "Because the Equator gets more heat, ocean currents and winds carry warmth towards the poles. The Gulf Stream brings warm Atlantic water towards north-west Europe." }
  ],

  // Climate Zones
  "mt_TMOzMCE17H": [
    { q: "Which climate zone is hot and wet all year round, near the Equator?", a: ["Tropical", "Polar", "Temperate", "Arid"], why: "Tropical climates near the Equator are hot all year with lots of rain, which is why rainforests like the Amazon grow there." },
    { q: "Which climate zone does the UK belong to?", a: ["Temperate", "Tropical", "Polar", "Arid (desert)"], why: "The UK has a temperate climate: mild, with four seasons and rain spread through the year. It is rarely extremely hot or extremely cold." },
    { q: "What is the main feature of an arid (desert) climate?", a: ["Very little rain", "Snow all year round", "Four mild seasons", "Thick rainforest"], why: "Arid means very dry. Deserts get very little rain, and they are not always hot: Antarctica is the biggest desert of all!" },
    { q: "What mostly decides which climate zone a place is in?", a: ["How far it is from the Equator", "How many people live nearby", "Which time zone it is in", "How old the rocks underneath are"], why: "Latitude (distance from the Equator) is the biggest factor, because places nearer the Equator get stronger sunshine. Height and distance from the sea matter too." },
    { q: "Why can there be snow on top of Mount Kilimanjaro in Africa, even though it is near the Equator?", a: ["It gets colder the higher you go", "It is close to the North Pole", "Snow is blown there from Antarctica", "It is in shadow most of the day"], why: "Air gets colder with height, roughly 6 to 7 °C cooler for every 1,000 m. Kilimanjaro is nearly 6,000 m tall, so its top has a cold mountain climate." },
    { q: "Which animal is best suited to a polar climate?", a: ["Polar bear", "Camel", "Toucan", "Orangutan"], why: "Polar bears have thick fur and a layer of fat (blubber) to keep warm in freezing temperatures. Camels suit deserts; toucans and orangutans suit tropical rainforests." },
    { q: "In hot deserts, many traditional houses have thick walls and small windows. Why?", a: ["To keep the inside cool in the heat", "To let in as much sunlight as possible", "To stop snow from piling up", "To keep out heavy tropical rain"], why: "Thick walls soak up the daytime heat slowly and small windows let in less sun, so homes stay cooler. Climate shapes how people build and live." },
    { q: "A place at sea level, far to the north near the Arctic, has long freezing winters, very short summers and almost no trees. Which zone is it in?", a: ["Polar", "Tropical", "Temperate", "Arid"], why: "Being far from the Equator means weak sunshine and long, dark winters. This gives a polar climate, where only small, tough plants can grow." }
  ],

  // Climate Change Basics
  "mt_DbI1kNg_0R": [
    { q: "What is the greenhouse effect?", a: ["The atmosphere trapping some heat", "Plants growing faster in glasshouses", "The Sun itself getting hotter", "Heat escaping through a hole"], why: "Gases such as carbon dioxide act a bit like a blanket, trapping some heat near Earth's surface. Without any greenhouse effect Earth would be freezing." },
    { q: "Which gas, released when we burn fossil fuels, is the main cause of the extra warming?", a: ["Carbon dioxide", "Oxygen", "Helium", "Nitrogen"], why: "Burning coal, oil and gas releases carbon dioxide (CO₂). Extra CO₂ thickens the 'blanket' of greenhouse gases, so the planet traps more heat." },
    { q: "Which of these is a fossil fuel?", a: ["Coal", "Wind", "Sunlight", "Wood"], why: "Coal, oil and natural gas formed over millions of years from the remains of ancient plants and animals. Wood is a fuel, but it is not a fossil fuel." },
    { q: "Why are sea levels rising as the world warms?", a: ["Land ice melts and warm water expands", "More rivers are being dug each year", "The Moon is pulling the sea higher", "Fish are making the oceans fuller"], why: "Melting glaciers and ice sheets add water to the sea, and water takes up more space as it warms. Both raise sea levels, threatening low-lying coasts." },
    { q: "Melting sea ice floating in the Arctic hardly raises sea level, but melting ice on Greenland's land does. Why?", a: ["Floating ice already pushes water aside", "Arctic ice is too salty to melt fully", "Greenland ice is far heavier for its size", "Arctic meltwater turns straight to gas"], why: "Floating ice already takes up space in the sea, like ice cubes in a glass of water. Ice on land adds new water to the ocean when it melts." },
    { q: "Which of these would reduce the carbon dioxide we add to the air?", a: ["Using electricity from wind turbines", "Burning more coal in power stations", "Cutting down large forests", "Driving petrol cars more often"], why: "Wind turbines make electricity without burning fuel, so they release almost no CO₂ while working. Trees take in CO₂, so cutting forests down makes things worse." },
    { q: "Which of these is a likely effect of global warming?", a: ["More frequent heatwaves", "Earth stops spinning", "Sea levels fall sharply", "Fewer extreme weather events"], why: "A warmer world brings more heatwaves and changes rain patterns. The UK recorded its first temperature over 40 °C in July 2022." },
    { q: "True or false: one very cold winter in Britain proves that global warming has stopped.", a: ["False", "True"], why: "Weather is what happens day to day; climate is the pattern over many years. Global warming is measured as a long-term average across the whole planet." }
  ],

  // Locating places with latitude and longitude
  "mt_eDaSAl6DwW": [
    { q: "Latitude tells you how far a place is…", a: ["North or south of the Equator", "East or west of Greenwich", "Above or below sea level", "From the nearest capital city"], why: "Latitude measures position north or south of the Equator, from 0° at the Equator to 90° at each pole. Longitude measures east or west." },
    { q: "The Prime Meridian (0° longitude) passes through which place in London?", a: ["Greenwich", "Westminster", "Wimbledon", "Heathrow"], why: "The Prime Meridian runs through the Royal Observatory at Greenwich. Places are measured in degrees east or west of this line, up to 180°." },
    { q: "What is the latitude of the Equator?", a: ["0°", "90°", "180°", "45°"], why: "The Equator is the starting line for latitude, so it is 0°. The North Pole is 90°N and the South Pole is 90°S." },
    { q: "Lines of longitude run from the North Pole to the South Pole. What do their values measure?", a: ["How far east or west a place is", "How far north or south a place is", "How far a place is from the North Pole", "How high a place is above the sea"], why: "It's easy to mix up: lines of longitude run north–south, but they measure position east or west of the Prime Meridian. Lines of latitude run east–west but measure north–south." },
    { q: "Which of these positions is in the Southern Hemisphere?", a: ["34°S, 18°E", "51°N, 10°W", "40°N, 74°W", "35°N, 139°E"], why: "S means south of the Equator, so 34°S, 18°E is in the Southern Hemisphere. It is close to Cape Town in South Africa. The others are all north (N)." },
    { q: "A position is written as 40°N, 74°W. What does the 74°W part tell you?", a: ["It is 74° west of the Prime Meridian", "It is 74° north of the Equator", "It is 74 km west of Greenwich", "It is 74° south of the North Pole"], why: "Coordinates are usually given as latitude, then longitude. 40°N is the latitude; 74°W means 74° west of the Prime Meridian. This spot is near New York." },
    { q: "On a globe, lines of longitude 10° apart are far apart at the Equator. What happens to the gap between them near the poles?", a: ["It shrinks until the lines meet", "It stays the same as at the Equator", "It gets wider and wider", "The lines stop at the Arctic Circle"], why: "All lines of longitude meet at the poles. 10° of longitude is about 1,100 km at the Equator but much less near the poles, so equal degrees don't mean equal distances." },
    { q: "A radio message says a ship is 'at 50°N'. Why is this not enough to find the ship?", a: ["It gives latitude but not longitude", "50°N is not a real latitude", "Ships at sea have no latitude", "It needs the name of a nearby town"], why: "50°N is a whole line circling the Earth. You also need the longitude (east or west) to pin down the one point where the two lines cross." }
  ],

  // ===================== TIME TUNNEL =====================

  // The Pharaoh as Living God
  "mt_PCX1jZZnf9": [
    { q: "Ancient Egyptians believed their pharaoh was…", a: ["A god on Earth as well as a ruler", "An ordinary person chosen by vote", "A priest with no power to rule", "A foreign king from far away"], why: "The pharaoh was both king and a living god, linked to the god Horus. He was believed to stand between the gods and the people." },
    { q: "What was Ma'at in ancient Egypt?", a: ["The idea of truth, justice and order", "The river that flooded every year", "The name of the first pyramid", "A type of Egyptian picture writing"], why: "Ma'at meant truth, justice, balance and order. Pharaohs were expected to uphold it, and laws were meant to follow it. Ma'at was also a goddess, shown with a feather." },
    { q: "Who ran the government day to day on the pharaoh's behalf?", a: ["The vizier", "The farmers", "The embalmers", "The fishermen"], why: "The vizier was the pharaoh's chief minister. He oversaw officials, taxes, courts and building projects, while scribes kept the written records." },
    { q: "Why was it so important for the pharaoh to keep Ma'at?", a: ["To keep the world in order and balance", "To make the pyramids grow even taller", "To stop ordinary people learning to write", "To decide who won the chariot races"], why: "Egyptians believed that if the pharaoh kept Ma'at, the gods would be pleased, the Nile would flood properly and chaos would be kept away." },
    { q: "A temple carving shows the pharaoh making offerings to the gods. What does this tell us about his role?", a: ["He was the link between gods and people", "He was a servant who cleaned the temple", "He didn't believe in the gods", "He was being punished by the priests"], why: "Pharaohs were seen as the go-between linking the gods and the Egyptian people. In theory he was the high priest of every temple, though priests did the daily rituals." },
    { q: "Pharaohs are often shown holding two objects as symbols of their power. What are they?", a: ["A crook and a flail", "A sword and a shield", "A laurel wreath and a lyre", "A trident and a net"], why: "The crook (a shepherd's staff) and the flail stood for the pharaoh caring for and ruling his people. Tutankhamun's golden coffin shows him holding both." },
    { q: "Hatshepsut was a female pharaoh. How is she often shown in statues?", a: ["With a false beard, like a male king", "Wearing a Roman toga and leather sandals", "Riding a horse at the head of an army", "As a tiny figure behind the vizier"], why: "Hatshepsut ruled in the 1400s BC. Statues often show her with the pharaoh's false beard and kingly clothes, because those symbols showed royal power." },
    { q: "Egypt was divided into about 40 provinces called nomes. Who governed each nome for the pharaoh?", a: ["A local governor called a nomarch", "An elected council of local farmers", "A Roman general and his legions", "A priest sent from ancient Greece"], why: "Each nome was run by a nomarch, an official who collected taxes and kept order. Nomarchs answered to the vizier and the pharaoh." }
  ],

  // Egyptian Art and Architecture
  "mt__qlBYNP62H": [
    { q: "In Egyptian paintings, how were people's heads usually shown?", a: ["Face side-on, eye drawn from the front", "Completely from the front, like a photo", "From directly above, like a map", "From behind, facing away from us"], why: "Egyptian artists showed each body part from its clearest angle: face and legs from the side, eye and shoulders from the front. The aim was clarity, not realism." },
    { q: "In an Egyptian wall painting, the pharaoh is drawn much bigger than his servants. Why?", a: ["Size showed how important someone was", "The pharaoh was really a giant", "He was standing closer to the artist", "The servants were young children"], why: "Egyptian art used size to show importance, not real height. Pharaohs and gods are drawn biggest; servants and enemies are smaller." },
    { q: "Put these Egyptian royal tomb designs in order, oldest first.", a: ["Mastaba, step pyramid, smooth pyramid", "Smooth pyramid, mastaba, step pyramid", "Step pyramid, smooth pyramid, mastaba", "Smooth pyramid, step pyramid, mastaba"], why: "Early tombs were flat-topped mastabas. Djoser's step pyramid stacked layers like mastabas, and later builders made smooth-sided pyramids like those at Giza." },
    { q: "Why did pharaohs build enormous pyramids and temples?", a: ["To show power and honour the gods", "To store spare grain for winter", "To give tourists something to see", "To block sandstorms from the cities"], why: "Huge monuments showed the pharaoh's power and honoured the gods. Pyramids were tombs, built to protect the pharaoh's body for the afterlife." },
    { q: "Djoser's pyramid at Saqqara, built in about 2650 BC, is the oldest Egyptian pyramid. What kind of monument is it?", a: ["A step pyramid", "A smooth-sided pyramid", "A rock-cut temple", "A tall, thin obelisk"], why: "Djoser's architect, Imhotep, stacked six layers of stone, each smaller than the one below. It is one of the oldest large stone buildings in the world." },
    { q: "The two temples at Abu Simbel, built for Ramesses II, are unusual because they were…", a: ["Carved into a solid rock cliff", "Built entirely from mud bricks", "Made of wood and painted gold", "Built floating on the River Nile"], why: "Abu Simbel was cut into a sandstone cliff, with four giant seated statues of Ramesses II at the front. In the 1960s it was moved to escape a new reservoir." },
    { q: "What is an obelisk?", a: ["A tall, four-sided stone pillar", "A flat-topped tomb made of brick", "A painted wooden coffin", "A temple carved into a cliff"], why: "Obelisks are tall, tapering stone pillars with pyramid-shaped tips, often carved with hieroglyphs. Cleopatra's Needle in London is an ancient Egyptian obelisk." },
    { q: "Later pharaohs were buried in hidden tombs cut into the rock of the Valley of the Kings instead of in pyramids. What is the most likely reason?", a: ["Pyramids were easy targets for robbers", "Egypt had run out of building stone", "Pyramids were thought to be unlucky", "The desert sand had become too soft"], why: "Almost every pyramid was robbed. Hidden tombs cut into the valley rock were harder to find: Tutankhamun's tomb was found largely intact in 1922." }
  ],

  // Roman Republic and Empire
  "mt_vFYFvgrPgD": [
    { q: "In the Roman Republic, who were the two leaders elected each year to run the government and lead the army?", a: ["Consuls", "Emperors", "Pharaohs", "Kings"], why: "Two consuls were elected every year, so no single person held power for long. Each consul could block the other's decisions." },
    { q: "What was the Roman Senate?", a: ["A powerful council of leading Romans", "The cavalry section of the Roman army", "The emperor's private team of guards", "A large market for selling grain"], why: "The Senate was a council of senior men, at first mostly from rich patrician families. It advised the consuls and had great influence over laws and money." },
    { q: "In the Roman Republic, who were the plebeians?", a: ["Ordinary Roman citizens", "Rich noble families", "Enemy soldiers from abroad", "Priests of the god Jupiter"], why: "Plebeians were the ordinary citizens: farmers, craftspeople and traders. Patricians were the old, wealthy noble families who at first held most power." },
    { q: "Who became the first Roman emperor, in 27 BC?", a: ["Augustus", "Julius Caesar", "Nero", "Romulus"], why: "Augustus (earlier called Octavian) became the first emperor in 27 BC. Julius Caesar, his great-uncle, was a powerful dictator but never an emperor." },
    { q: "What was the Pax Romana?", a: ["A long period of peace in the empire", "A famous chariot race held in Rome", "The first written Roman book of laws", "A long war between Rome and Carthage"], why: "Pax Romana means 'Roman Peace'. It began under Augustus and lasted about 200 years, with fewer wars inside the empire and growing trade." },
    { q: "In ancient Athens, citizens voted on decisions themselves. In the Roman Republic, citizens mostly elected officials. What was the Athenian system called?", a: ["Direct democracy", "Elected republic", "Military empire", "Hereditary monarchy"], why: "In Athenian direct democracy, citizens (free men only) debated and voted in the Assembly themselves. In Rome, citizens elected officials, who governed with the Senate." },
    { q: "Consuls served for one year, but emperors such as Nero ruled for life. What problem could this cause?", a: ["A cruel ruler could stay in power for years", "Emperors had to be re-elected each year", "The army refused to fight for an emperor", "The Senate grew more powerful than ever"], why: "Nero ruled from AD 54 to 68 and is remembered as a cruel emperor. Unlike consuls, emperors couldn't simply be voted out; Nero fell only when the army and Senate turned on him." },
    { q: "Augustus called himself 'first citizen' and let the Senate keep meeting. Why do historians still say Rome had become an empire?", a: ["Real power was now held by one man", "The Senate had been abolished", "Rome had stopped conquering land", "Citizens were banned from Rome"], why: "The Senate still met, but Augustus controlled the army and money and chose who held top jobs. Rome kept the look of a republic while one man ruled." }
  ],

  // Fall of the Western Roman Empire
  "mt_H4bLNkDrGJ": [
    { q: "In which year was the last emperor of the Western Roman Empire removed from power?", a: ["AD 476", "AD 43", "AD 1066", "AD 410"], why: "In AD 476 a Germanic leader, Odoacer, removed the teenage emperor Romulus Augustulus. Historians use this date for the fall of the Western Empire." },
    { q: "Which of these was a reason the Western Roman Empire declined?", a: ["Attacks by invading peoples", "The invention of gunpowder", "A war with the Normans", "Too few roads being built"], why: "Groups such as the Goths, Vandals and Huns pushed into the empire. Defending long borders against them stretched Rome's army and money." },
    { q: "What happened to the Eastern Roman Empire after the West fell in AD 476?", a: ["It lasted almost another 1,000 years", "It fell to invaders at the same time", "It was conquered by Egypt soon after", "It was ruled from Britain from then on"], why: "The Eastern (Byzantine) Empire, ruled from Constantinople, survived until the Ottoman Turks captured the city in 1453." },
    { q: "Roman rule in Britain ended in about AD 410. Why had most Roman soldiers left Britain?", a: ["To defend the empire closer to Rome", "Britain had become too hot for them", "They had conquered Scotland instead", "The Britons had paid them to leave"], why: "With invaders threatening Italy and Gaul, the empire pulled troops away from Britain. By about AD 410 Roman rule in Britain had ended." },
    { q: "In the AD 200s, Rome had more than 20 emperors in about 50 years, and many were killed. Which problem does this show?", a: ["Political instability", "Too much peace", "A shortage of coins", "Strong, steady leadership"], why: "When leaders keep changing and fighting for power, government is weak, and armies fight each other instead of guarding the borders." },
    { q: "Later Roman emperors put less and less silver into their coins. What problem did this cause?", a: ["Money was worth less and prices rose", "Coins became far too heavy to carry", "People stopped paying any taxes", "Silver mines filled up with water"], why: "Mixing cheaper metals into coins made each coin worth less, so prices went up. Money trouble made it harder to pay the army." },
    { q: "Why did the empire's huge size become a problem?", a: ["Its long borders were hard to defend", "There were far too few people to tax", "Its cities were too far from the sea", "Its weather was the same everywhere"], why: "At its largest the empire stretched from Britain to the Middle East. Guarding thousands of miles of frontier took huge armies and lots of money." },
    { q: "A pupil writes: 'Rome fell because of just one thing: the Goths.' What would most historians say?", a: ["No, several causes worked together", "Yes, the Goths were the only cause", "No, it was really the Vikings alone", "No, a single earthquake destroyed it"], why: "Most historians agree there was no single cause. Invasions, weak government, money trouble and a vast empire combined over a long time." }
  ],

  // Greek Philosophers and Medicine
  "mt_cUMUYkDqZp": [
    { q: "Which Greek thinker is famous for teaching by asking lots of questions?", a: ["Socrates", "Hippocrates", "Archimedes", "Homer"], why: "Socrates questioned people to test their ideas and help them think for themselves. This way of learning is called the Socratic method." },
    { q: "Why is Hippocrates called 'the father of medicine'?", a: ["He looked for natural causes of illness", "He invented the very first antibiotics", "He built the first big hospital in Rome", "He found how blood flows round the body"], why: "Hippocrates taught that illness has natural causes, not punishment from the gods. His doctors studied symptoms carefully. Some doctors still take a 'Hippocratic Oath'." },
    { q: "Which Greek thinker carefully observed animals and plants and sorted them into groups?", a: ["Aristotle", "Socrates", "Plato", "Pythagoras"], why: "Aristotle studied and classified hundreds of kinds of animals by observing them closely. Sorting living things into groups is still a key part of science." },
    { q: "Plato wrote a famous book called The Republic. What was it mainly about?", a: ["His idea of a perfect, fair society", "A history of the Roman Empire", "How to build temples and columns", "A guide to the Olympic Games"], why: "In The Republic, Plato imagined an ideal city ruled by wise 'philosopher kings'. People still debate his ideas about justice and government." },
    { q: "A teacher answers a pupil's question with another question: 'What do you think makes someone brave?' Which method is she using?", a: ["The Socratic method", "The scientific method", "The Hippocratic method", "The Roman method"], why: "The Socratic method means learning by being asked questions that make you examine your own ideas, rather than just being told the answer." },
    { q: "A patient in ancient Greece has a fever. Which advice would a follower of Hippocrates most likely give?", a: ["Rest, eat well and let the doctor watch", "Make a sacrifice to calm angry gods", "Ignore it, as illness can't be explained", "Wear a lucky charm to scare off spirits"], why: "Hippocratic doctors believed illness had natural causes. They observed symptoms and recommended rest, a good diet and exercise rather than relying on the gods." },
    { q: "Socrates taught Plato, and Plato taught Aristotle. Who did Aristotle go on to teach?", a: ["Alexander the Great", "Julius Caesar", "Tutankhamun", "Richard the Lionheart"], why: "Aristotle was tutor to the young Alexander of Macedon, who later built a huge empire. This chain of teachers shaped Western thinking for centuries." },
    { q: "True or false: Socrates wrote many books explaining his ideas.", a: ["False", "True"], why: "Socrates didn't write his ideas down. We know about him mainly from his pupil Plato, who wrote conversations (dialogues) featuring Socrates." }
  ],

  // Greek and Roman Architecture
  "mt_lzCcQzPJZi": [
    { q: "Which Greek column style is the plainest, with a simple, sturdy top?", a: ["Doric", "Ionic", "Corinthian", "Gothic"], why: "Doric columns are thick and plain with a simple, cushion-like top (capital). The outer columns of the Parthenon in Athens are Doric." },
    { q: "A column has a top (capital) shaped like two curling scrolls. Which style is it?", a: ["Ionic", "Doric", "Corinthian", "Tuscan"], why: "Ionic capitals have scroll shapes called volutes, a bit like a rolled-up piece of paper at each side." },
    { q: "Which Greek column style has a capital decorated with carved leaves?", a: ["Corinthian", "Doric", "Ionic", "Norman"], why: "Corinthian is the fanciest Greek style, with acanthus leaves carved around the capital. The Romans used it a great deal." },
    { q: "Which building shape did the Romans use widely in bridges, aqueducts and the Colosseum?", a: ["The rounded arch", "The pointed spire", "The steel frame", "The flying buttress"], why: "A rounded arch spreads weight down and outwards, so it can span wide gaps. Romans used arches in aqueducts, bridges and the Colosseum." },
    { q: "The Pantheon in Rome, nearly 1,900 years old, has a huge dome. Which Roman building material was it made from?", a: ["Concrete", "Steel", "Plastic", "Glass"], why: "Romans made concrete from lime, volcanic ash and rubble. The Pantheon's dome is still the largest unreinforced concrete dome in the world." },
    { q: "The front of the British Museum in London has a row of tall columns holding up a triangular roof section. Which style inspired it?", a: ["Ancient Greek temples", "Ancient Egyptian pyramids", "Medieval castles", "Viking longhouses"], why: "The British Museum, built in the 1800s, copies a Greek temple front: Ionic columns holding up a triangular pediment. Many banks, courts and museums do the same." },
    { q: "Why can a stone arch carry a heavy load without a beam across the top?", a: ["Each stone pushes weight onto the next", "The top stone is lighter than the rest", "The stones are held in place by glue", "Air under the arch pushes it upwards"], why: "Each wedge-shaped stone in an arch pushes against its neighbours. The weight is passed sideways and down into the supports, so the stones squeeze tightly together." },
    { q: "Why was concrete so useful to Roman builders?", a: ["It could be shaped before it set hard", "It was lighter than wood and floated", "It could be mixed without water", "It was clear like glass, letting in light"], why: "Concrete starts as a wet mix that can be poured into shapes, then sets hard, even underwater with the right ash. It let Romans build domes, vaults and harbours." }
  ],

  // Magna Carta and Limiting Royal Power
  "mt_8ShghTx0jd": [
    { q: "In 1215, King John met his rebel barons at Runnymede, beside the River Thames. What did he agree to there?", a: ["Magna Carta", "The Domesday Book", "The Bill of Rights", "The Act of Union"], why: "King John agreed to Magna Carta at Runnymede in June 1215. The Domesday Book (1086), Bill of Rights (1689) and Act of Union (1707) came at other times." },
    { q: "True or false: King John signed Magna Carta with his signature.", a: ["False", "True"], why: "John didn't sign it. Documents were approved by attaching the royal seal, a wax stamp. Copies were then written out by hand and sent around the kingdom." },
    { q: "Why did the barons rebel against King John?", a: ["He taxed them heavily and ruled unfairly", "He refused to let them build castles", "He gave them too much land and power", "He wanted England to become a republic"], why: "John demanded heavy taxes to pay for failed wars in France, punished barons without fair trials and quarrelled with the Pope. The barons had had enough." },
    { q: "What was the big idea behind Magna Carta?", a: ["Even the king must obey the law", "The king can make any law he likes", "Barons should rule instead of kings", "People should elect their king"], why: "Magna Carta set out that the king was not above the law. He had to follow rules too, just like his subjects." },
    { q: "One famous part of Magna Carta says no free man can be imprisoned or punished except after what?", a: ["A fair trial under the law of the land", "A vote of all the bishops in England", "The decision of the strongest knight", "The king's own wishes on that day"], why: "It said free men could only be punished after lawful judgement by their equals or by the law of the land: an early step towards the right to a fair trial." },
    { q: "What happened soon after Magna Carta was sealed in 1215?", a: ["The Pope cancelled it and war broke out", "John and the barons became best friends", "John gave up his crown the next day", "Schools began teaching it straight away"], why: "Within months John asked the Pope to cancel it, and the First Barons' War began. After John died in 1216, Magna Carta was reissued and kept alive." },
    { q: "Why is Magna Carta still important today?", a: ["Its ideas shaped later rights and laws", "It gave women the right to vote", "It turned England into a republic", "It stopped kings from collecting taxes"], why: "Its ideas, that rulers must obey the law and people deserve fair trials, influenced later laws around the world, including the United States Constitution." },
    { q: "Only three of Magna Carta's clauses are still law in England today. What does this suggest about why it is famous?", a: ["Its big ideas matter more than details", "Its clauses were copied from Roman law", "It was mainly about building churches", "Most of it was secretly rewritten later"], why: "Most clauses dealt with problems of 1215, like fish traps in rivers and payments by barons. It is remembered for its big idea: rulers must obey the law." }
  ],

  // Towns & Trade
  "mt_UMOjbmLcbM": [
    { q: "What was a medieval guild?", a: ["A group of workers in the same trade", "A strong wall built around a castle", "A tax that peasants paid to their lord", "A large church in the middle of town"], why: "Guilds were groups of people in the same trade, like bakers or weavers. They set prices and quality standards, trained apprentices and helped members in need." },
    { q: "How were medieval towns usually different from villages?", a: ["More people, markets and workshops", "Quieter, with fewer shops and traders", "Mainly fields of crops and sheep", "Smaller, with houses spread far apart"], why: "Towns had more people, regular markets, craft workshops and often walls with gates. Most villagers farmed the land around them." },
    { q: "What did a young person do as an apprentice?", a: ["Learned a trade by working for a master", "Collected taxes on behalf of the king", "Guarded the town gates through the night", "Ran the town's weekly market stalls"], why: "Apprentices lived and worked with a master craftsman for several years, often about seven, learning the trade before they could become skilled workers." },
    { q: "What was a town charter?", a: ["A grant of rights to run its own affairs", "A map showing the main roads to market", "A list of the animals kept in the town", "A ship that carried English wool abroad"], why: "Kings or lords granted charters that let towns hold markets, collect some taxes and choose their own leaders. Townspeople often paid for these rights." },
    { q: "In medieval England, which product was the most important export, making many merchants rich?", a: ["Wool", "Tea", "Potatoes", "Chocolate"], why: "English wool was in great demand by cloth-makers abroad. Tea, potatoes and chocolate hadn't reached England yet. The Lord Speaker still sits on a Woolsack!" },
    { q: "A historian finds a medieval guild's rule book that lists fines for poor work. What can it best tell us?", a: ["The standards the guild expected", "How well members really worked", "How many people lived in the town", "What the king thought of the guild"], why: "Rules show what a guild wanted, not what always happened. Fines for poor work even hint that some members broke the rules. Court records could show how often." },
    { q: "Why could life in a town give people more freedom than life in a village?", a: ["They weren't tied to a lord's land", "They didn't have to pay any taxes", "They could each be made a knight", "They were allowed to choose the king"], why: "Many villagers were serfs who had to work their lord's land. In some towns, a serf who lived there for a year and a day could become free." },
    { q: "As trade grew, a new group of wealthy people appeared who were neither lords nor peasants. Who were they?", a: ["Merchants", "Soldiers", "Monks", "Serfs"], why: "Merchants grew rich buying and selling goods like wool and cloth. Some became town leaders, like Richard Whittington, a merchant who was Lord Mayor of London." }
  ],

  // Printing Press & Renaissance
  "mt_rf23aL6KwH": [
    { q: "Who developed a printing press with movable metal type in Europe around 1450?", a: ["Johannes Gutenberg", "William Shakespeare", "Leonardo da Vinci", "Isaac Newton"], why: "Johannes Gutenberg, working in Mainz in Germany, built a press using movable metal letters. His famous Bible was printed in the mid-1450s." },
    { q: "Who brought printing to England, setting up a press at Westminster in 1476?", a: ["William Caxton", "Geoffrey Chaucer", "King Henry VIII", "Thomas Becket"], why: "William Caxton learned printing abroad and set up England's first printing press at Westminster in 1476. He printed Chaucer's Canterbury Tales." },
    { q: "How were most books made in Europe before the printing press?", a: ["Copied out by hand, often by monks", "Printed by machines in factories", "Typed out on typewriters", "Photocopied from older books"], why: "Scribes, many of them monks, copied books by hand. A single book could take months, so books were rare and very expensive." },
    { q: "What was so clever about movable type?", a: ["Letters could be reused for new pages", "Each page was carved from one block", "It printed full-colour photographs", "It worked without using any ink"], why: "Single metal letters were arranged into words, inked and printed, then reused for the next page. This was much faster than copying or carving whole pages." },
    { q: "Far more written sources survive from England in 1600 than from 1300. Which is one important reason?", a: ["Printing made many more copies", "People in 1300 could not speak", "Paper had not yet been invented", "Historians may not study 1300"], why: "Before printing, every copy was written by hand, so fewer were made and fewer survived. Printed books came in hundreds of copies, and more people could read by 1600." },
    { q: "Printers like Caxton produced many identical copies of books written in English. What was one long-term effect?", a: ["English spelling slowly became more fixed", "People in England stopped writing English", "Latin was banned in English churches", "English writers switched to French"], why: "When many identical copies were printed, the same spellings were seen again and again. Over a long time this helped English spelling become more standard." },
    { q: "What does the word 'Renaissance' mean?", a: ["Rebirth", "Darkness", "Invention", "Kingdom"], why: "Renaissance means 'rebirth'. From about the 1300s to the 1600s, starting in Italy, people revived interest in ancient Greek and Roman learning, art and ideas." },
    { q: "How did printing help the Renaissance spread from Italy across Europe?", a: ["Books carried new ideas across borders", "It stopped people travelling abroad", "It made Latin illegal everywhere", "It kept the new ideas inside Italy"], why: "Printed copies of ancient texts and new works travelled quickly, so Renaissance ideas reached places like England far faster than hand-copied books could." }
  ],

  // Questioning Historical Sources
  "mt_TTzJTF-OkG": [
    { q: "Before trusting a historical source, which three questions are most useful to ask first?", a: ["Who made it, when, and why?", "How heavy, how big, how shiny?", "What colour, size and shape is it?", "Where is it kept and what's it worth?"], why: "Who made a source, when and why it was made all affect how reliable it is and what it can tell us. Historians ask these first." },
    { q: "What is a primary source?", a: ["Something made at the time being studied", "A modern textbook written about the past", "A film made today about a time in history", "A website that summarises old events"], why: "Primary sources come from the time itself, like a Roman coin, a medieval charter or a diary. Secondary sources are made later by people studying the past." },
    { q: "A Roman writer describes the Britons as wild and uncivilised. Why should we be careful with this source?", a: ["The writer may have been biased against them", "Romans did not really settle in Britain", "The writer was born a thousand years later", "Latin cannot be translated today"], why: "Romans were the invaders and often saw other peoples as inferior. The Britons left few written records of their own, so we hear mostly the Roman view." },
    { q: "A medieval king's own official writer describes him as brave, wise and always right. What is the main problem with this source?", a: ["It was written to make the king look good", "Medieval writing is impossible to read", "It is written in old-fashioned words", "It is too old to tell us anything"], why: "Someone paid by the king had a reason to praise him. The source is still useful, as it shows how the king wanted to be seen, but it is not neutral." },
    { q: "Two accounts of the Battle of Hastings (1066) are found: one written in 1070, one in 1850. Why might historians value the 1070 account more?", a: ["It was written much closer to the event", "Older ink is much easier to read today", "It must have been written by a king", "Victorian books are hard to find"], why: "A source from close to the time may be based on eyewitnesses. It still needs checking, though: who wrote it, and why, matter too." },
    { q: "The Bayeux Tapestry tells the story of 1066. It was made for the Normans soon after they won. Whose side of the story does it most likely show?", a: ["The Normans' side", "The Anglo-Saxons' side", "The Vikings' side", "A neutral, balanced view"], why: "It was probably made for Bishop Odo, William the Conqueror's half-brother, so it tells the story in a way that supports the Norman victory." },
    { q: "A historian knows a source is biased. What is the best way to use it?", a: ["Compare it with other sources", "Throw it away as useless", "Believe every word of it", "Change it to remove the bias"], why: "Biased sources can still be useful: they show what people believed or wanted others to believe. Cross-checking with other sources helps find what really happened." },
    { q: "True or false: if a source is very old, it must be telling the truth.", a: ["False", "True"], why: "Old sources can be mistaken, one-sided or exaggerated. Historians check who made them, when and why before deciding how far to trust them." }
  ]
});
